def jl(path, rows):
    with open(path, "w") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")


def build(out):
    out = Path(out)
    with open(out / "findings.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(F_COLS)
        for i, r in enumerate(FINDINGS, 1):
            w.writerow([f"ADV-{i:03d}", *r])
    jl(out / "evidence.jsonl", [dict(evidence_id=f"EV-ADV-{i:03d}", claim=c, value=v, unit=u, source_url_or_path=s, source_type=t, filing_period=p, accessed="2026-11-25", quality=q, notes=n)
                                for i, (c, v, u, s, t, p, q, n) in enumerate(EV, 1)])
    jl(out / "assumptions.jsonl", [dict(assumption_id=f"A-ADV-{i:03d}", statement=s, value=v, unit=u, low=lo, high=hi, basis=b, evidence_ids=e, sensitivity=se)
                                   for i, (s, v, u, lo, hi, b, e, se) in enumerate(AS, 1)])
    with open(out / "assumption-challenge-adv.csv", "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=TEMPLATE_COLS + EXTRA_COLS)
        w.writeheader()
        for r in CH:
            missing = [c for c in TEMPLATE_COLS if not r.get(c)]
            assert not missing, (r["assumption_id"], missing)
            w.writerow(r)
    from report_text import SECTIONS
    jl(out / "report.jsonl", [dict(section=s, markdown=m) for s, m in SECTIONS])


if __name__ == "__main__":
    sys.path.insert(0, str(Path(__file__).parent))
    build(sys.argv[1])
